with cleaned as (select id, customer_id, store_id, order_date, status, amount, discount, case when channel = 'web' then 1 else 0 end as is_web, length(status) as status_length from orders where customer_id is not null) select * from (select customer_id, status, amount from cleaned) src pivot (max(amount) as value_sum, count(1) as cnt for status in ('PENDING' as pending, 'COMPLETED' as completed));
